def upload(self, actor_id: str, filename: str, content: bytes):
    name = Path(filename.replace("\\", "/")).name.strip()
    if not name or len(name) > 180 or any(ord(char) < 32 for char in name):
        raise BusinessError(400, "文件名无效")
    if len(content) > 10 * 1024 * 1024:
        raise BusinessError(413, "演示文件不能超过 10 MB")
    ident = uuid.uuid4().hex
    row = {"id": ident, "name": name, "size": len(content), "owner_id": actor_id, "storage_key": ident, "state": self.workflow.machine["initial"], "revision": 1}
    path = self.blobs / ident
    path.write_bytes(content)
    try:
        self.store.add_file(row)
    except Exception:
        path.unlink(missing_ok=True)
        raise
    self.bo_emit("upload", "commit", {"actor_id": actor_id, "filename": name, "size": len(content)}, {"file_id": ident, "owner_id": actor_id, "state": row["state"], "revision": 1}, row)
    return self.public_file(row)

