support:server.py::Handler.dispatch.snippet:
def dispatch(self):
    service = self.server.service
    path = urlsplit(self.path).path
    if self.command == "GET" and path == "/favicon.ico":
        self.send_response(204)
        self.end_headers()
        return
    if self.command == "GET" and path == "/app-config":
        raw = json.dumps({"graph_url": self.server.graph_url}).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        return self.wfile.write(raw)
    if self.command == "GET" and path == "/":
        raw = (service.root / "static/index.html").read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        return self.wfile.write(raw)
    if self.command == "POST":
        origin = self.headers.get("Origin")
        if origin and origin != "http://" + self.headers.get("Host", ""):
            raise BusinessError(403, "请求来源不允许")
        size = int(self.headers.get("Content-Length", "0"))
        if not 0 <= size <= 15 * 1024 * 1024:
            raise BusinessError(413, "请求内容太大")
        body = json.loads(self.rfile.read(size) or b"{}")
        if not isinstance(body, dict):
            raise BusinessError(400, "请求格式错误")
        if path == "/api/login":
            token, user = service.login(str(body.get("actor_id", "")), str(body.get("password", "")))
            return self.reply(200, user, {"Set-Cookie": "session=" + token + "; HttpOnly; SameSite=Strict; Path=/"})
    actor_id = service.actor(self.token())
    if self.command == "GET":
        if path == "/api/me":
            user = service.store.user(actor_id)
            return self.reply(200, {"id": actor_id, "name": user["name"]})
        if path == "/api/users":
            return self.reply(200, service.users(actor_id))
        if path == "/api/files":
            return self.reply(200, service.list_files(actor_id))
        parts = path.strip("/").split("/")
        if len(parts) in (3, 4) and parts[:2] == ["api", "files"]:
            if len(parts) == 4 and parts[3] == "download":
                name, content = service.download(actor_id, parts[2])
                return self.reply(200, content, {"Content-Disposition": "attachment; filename*=UTF-8''" + quote(name, safe="")})
            if len(parts) == 3:
                return self.reply(200, service.details(actor_id, parts[2]))
    if self.command == "POST":
        if path == "/api/logout":
            service.logout(self.token())
            return self.reply(200, {"ok": True}, {"Set-Cookie": "session=; Max-Age=0; HttpOnly; SameSite=Strict; Path=/"})
        if path == "/api/files":
            content = base64.b64decode(body.get("content_base64", ""), validate=True)
            return self.reply(201, service.upload(actor_id, str(body.get("filename", "")), content))
        parts = path.strip("/").split("/")
        if len(parts) == 4 and parts[:2] == ["api", "files"] and parts[3] == "share":
            return self.reply(200, service.share(actor_id, parts[2], str(body.get("recipient_id", ""))))
        if len(parts) == 4 and parts[:2] == ["api", "files"] and parts[3] == "revoke":
            return self.reply(200, service.revoke(actor_id, parts[2], str(body.get("recipient_id", ""))))
    raise BusinessError(404, "页面不存在")

